{
  "name": "SQR1三球六自由度运动平台",
  "name_en": "SQR1 Tri-Sphere Six-Axis Motion Stage",
  "manufacturer": "",
  "description": "一套通过EPICS控制的三球六自由度运动平台，可对X、Y、Z三个平移轴以及rX、rY、rZ三个转动轴进行单轴或联动控制。适用于实验中样品、光学元件或工装的精密定位与姿态调整。",
  "description_en": "An EPICS-controlled tri-sphere six-axis motion stage that supports individual or coordinated control of X, Y, Z translations and rX, rY, rZ rotations. It is used in laboratories for precise positioning and angular alignment of samples, optics, or fixtures.",
  "tag_hints": [
    "six-axis motion stage",
    "tri-sphere positioning",
    "precision alignment",
    "X Y Z translation",
    "rotational alignment",
    "EPICS motion control"
  ],
  "actions": [
    {
      "action_name": "auto-multi_axis_move",
      "description": "同时移动一个或多个轴到指定位置，或移动到预设位置。",
      "description_en": "Move one or more axes simultaneously to specified positions or to a preset position."
    },
    {
      "action_name": "auto-preset_list",
      "description": "返回可用的预设位置列表。",
      "description_en": "Return the list of available preset positions."
    },
    {
      "action_name": "auto-stop",
      "description": "停止全部轴的运动。",
      "description_en": "Stop motion on all axes."
    },
    {
      "action_name": "auto-sync_setpoints",
      "description": "将各轴设定值与当前位置读回同步，用于启动初始化或避免未初始化轴误动作。",
      "description_en": "Synchronize each axis setpoint with its current readback, typically for startup initialization or to avoid unintended motion of uninitialized axes."
    },
    {
      "action_name": "auto-move",
      "description": "移动单个轴到目标位置。",
      "description_en": "Move a single axis to a target position."
    },
    {
      "action_name": "auto-set",
      "description": "设置单个轴的目标位置并执行定位。",
      "description_en": "Set a single axis target position and perform the positioning move."
    }
  ]
}

